33. //==================================================================================================
34. // Memory Region Type
35. //==================================================================================================
36. 
37. ///
38. /// # Description
39. ///
40. /// A type that represents the type of a memory region.
41. ///
42. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
43. #[verus_verify]
44. pub enum MemoryRegionType {
45.     /// Usable memory.
46.     Usable,
47.     /// Reserved memory.
48.     Reserved,
49.     /// Memory mapped I/O.
50.     Mmio,
51.     /// Bad memory.
52.     Bad,
53. }
54. 
55. //==================================================================================================
56. // MMIO Cache Policy
57. //==================================================================================================
58. 
59. ///
60. /// # Description
61. ///
62. /// Caching policy for MMIO memory regions. Controls the PWT (Page Write-Through) and PCD
63. /// (Page Cache Disable) bits in the page table entries that back the region.
64. ///
65. #[verus_verify(external_derive)]
66. #[derive(Debug, Clone, Copy, Eq, PartialEq)]
67. pub struct MmioCachePolicy {
68.     /// If `true`, the page is mapped with the Write-Through attribute (PWT=1).
69.     write_through: bool,
70.     /// If `true`, caching is enabled for the page (PCD=0).
71.     cache_enabled: bool,
72. }
73. 
74. impl MmioCachePolicy {
75.     ///
76.     /// # Description
77.     ///
78.     /// Creates a new MMIO cache policy.
79.     ///
80.     /// # Parameters
81.     ///
82.     /// - `write_through`: If `true`, enables the Write-Through attribute (PWT=1).
83.     /// - `cache_enabled`: If `true`, enables caching for the page (PCD=0).
84.     ///
85.     /// # Returns
86.     ///
87.     /// A new [`MmioCachePolicy`] instance.
88.     ///
89.     pub const fn new(write_through: bool, cache_enabled: bool) -> Self {
90.         Self {
91.             write_through,
92.             cache_enabled,
93.         }
94.     }
95. 
96.     /// Uncacheable: Write-Through Enabled, Cache Disabled.
97.     pub const UNCACHEABLE: Self = Self {
98.         write_through: true,
99.         cache_enabled: false,
100.     };
101. 
102.     /// Write-Back: Write-Through Disabled, Cache Enabled.
103.     pub const WRITE_BACK: Self = Self {
104.         write_through: false,
105.         cache_enabled: true,
106.     };
107. 
108.     ///
109.     /// # Description
110.     ///
111.     /// Returns whether the Write-Through attribute is set.
112.     ///
113.     /// # Returns
114.     ///
115.     /// `true` if the page is mapped with the Write-Through attribute (PWT=1).
116.     ///
117.     pub fn write_through(&self) -> bool {
118.         self.write_through
119.     }
120. 
121.     ///
122.     /// # Description
123.     ///
124.     /// Returns whether caching is enabled.
125.     ///
126.     /// # Returns
127.     ///
128.     /// `true` if caching is enabled for the page (PCD=0).
129.     ///
130.     pub fn cache_enabled(&self) -> bool {
131.         self.cache_enabled
132.     }
133. }
134. //==================================================================================================
135. // Memory Region
136. //==================================================================================================
137. 
138. ///
139. /// # Description
140. ///
141. /// A memory region.
142. ///
143. #[verus_verify(external_derive)]
144. #[derive(Debug, Clone)]
145. pub struct MemoryRegion<T: Address> {
146.     name: String,
147.     start: T,
148.     size: usize,
149.     typ: MemoryRegionType,
150.     perm: AccessPermission,
151.     cache_policy: Option<MmioCachePolicy>,
152. }
153. 
154. impl<T: Address> MemoryRegion<T> {
155.     /// Maximum byte-length of a memory region name.
156.     const MEMORY_REGION_NAME_MAX: usize = 32;
157. 
158.     /// Creates a new memory region.
159.     pub fn new(
160.         name: &str,
161.         start: T,
162.         size: usize,
163.         typ: MemoryRegionType,
164.         perm: AccessPermission,
165.     ) -> Result<Self, Error> {
166.         // Check if name is too long (byte length).
167.         if name.len() > Self::MEMORY_REGION_NAME_MAX {
168.             let reason: &str = "memory region name is too long";
169.             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
170.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
171.         }
172. 
173.         // Check if size of the memory region is valid.
174.         if size == 0 {
175.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
176.         }
177. 
178.         // Check if memory region is too big.
179.         let start_raw_addr: usize = start.clone().into_raw_value();
180.         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
181.             Some(end_raw_addr) => end_raw_addr,
182.             None => {
183.                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
184.             },
185.         };
186. 
187.         // Check if memory region spans outside the address space.
188.         if end_raw_addr > T::max_addr() {
189.             return Err(Error::new(
190.                 ErrorCode::InvalidArgument,
191.                 "memory region spans outside the address space",
192.             ));
193.         }
194. 
195.         Ok(Self {
196.             name: name.to_string(),
197.             start,
198.             size,
199.             typ,
200.             perm,
201.             cache_policy: None,
202.         })
203.     }
204. 
205.     pub fn name(&self) -> String {
206.         self.name.clone()
207.     }
208. 
209.     /// Returns the first valid address that lies in the target memory region.
210.     #[verus_spec(result =>
211.         ensures
212.             result@ == self@.start,
213.     )]
214.     pub fn start(&self) -> T {
215.         self.start.clone_address()
216.     }
217. 
218.     /// Returns the size of the target memory region.
219.     #[verus_spec(result =>
220.         ensures
221.             result as int == self@.size,
222.     )]
223.     pub fn size(&self) -> usize {
224.         self.size
225.     }
226. 
227.     /// Returns the type of the target memory region.
228.     pub fn typ(&self) -> MemoryRegionType {
229.         self.typ
230.     }
231. 
232.     /// Returns the permissions of the target memory region.
233.     pub fn perm(&self) -> AccessPermission {
234.         self.perm
235.     }
236. 
237.     ///
238.     /// # Description
239.     ///
240.     /// Returns the MMIO cache policy of the target memory region, if set.
241.     ///
242.     /// # Returns
243.     ///
244.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
245.     ///
246.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
247.         self.cache_policy
248.     }
249. 
250.     ///
251.     /// # Description
252.     ///
253.     /// Sets the MMIO cache policy of the target memory region.
254.     ///
255.     /// # Parameters
256.     ///
257.     /// - `policy`: The cache policy to assign.
258.     ///
259.     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
260.         self.cache_policy = Some(policy);
261.     }
262. }
263. 
264. impl<T: Address> PartialEq for MemoryRegion<T> {
265.     fn eq(&self, other: &Self) -> bool {
266.         self.name == other.name
267.             && self.start == other.start
268.             && self.size == other.size
269.             && self.typ == other.typ
270.             && self.perm == other.perm
271.             && self.cache_policy == other.cache_policy
272.     }
273. }
274. 
275. impl<T: Address> Eq for MemoryRegion<T> {}
276. 
277. impl<T: Address> PartialOrd for MemoryRegion<T> {
278.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
279.         Some(self.cmp(other))
280.     }
281. }
282. 
283. impl<T: Address> Ord for MemoryRegion<T> {
284.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
285.         self.start.cmp(&other.start)
286.     }
287. }
288. 
289. //==================================================================================================
290. // Truncated Memory Region
291. //==================================================================================================
292. 
293. ///
294. /// # Description
295. ///
296. /// A memory region that has been truncated to a multiple of a page size.
297. ///
298. #[verus_verify(external_derive)]
299. #[derive(Clone)]
300. pub struct TruncatedMemoryRegion<T: Address>(MemoryRegion<PageAligned<T>>);
301. 
302. impl<T: Address> TruncatedMemoryRegion<T> {
303.     /// Creates a new truncated memory region.
304.     pub fn new(
305.         name: &str,
306.         start: PageAligned<T>,
307.         size: usize,
308.         typ: MemoryRegionType,
309.         perm: AccessPermission,
310.     ) -> Result<Self, Error> {
311.         // Truncate the size of the memory region to a multiple of the page size.
312.         let size: usize = ::sys::mm::align_up(size, PAGE_ALIGNMENT).ok_or_else(|| {
313.             let reason: &str = "align_up overflow";
314.             error!("TruncatedMemoryRegion::new(): {reason} (name={name:?}, size={size})");
315.             Error::new(ErrorCode::InvalidArgument, reason)
316.         })?;
317.         Ok(Self(MemoryRegion::new(name, start, size, typ, perm)?))
318.     }
319. 
320.     ///
321.     /// # Description
322.     ///
323.     /// Creates a new truncated MMIO memory region with an explicit cache policy.
324.     ///
325.     /// # Parameters
326.     ///
327.     /// - `name`: Name of the memory region.
328.     /// - `start`: Page-aligned start address.
329.     /// - `size`: Size of the region in bytes (rounded up to page alignment).
330.     /// - `perm`: Access permissions for the region.
331.     /// - `cache_policy`: Caching policy that controls PWT/PCD bits in page table entries.
332.     ///
333.     /// # Returns
334.     ///
335.     /// Upon successful completion, a new [`TruncatedMemoryRegion`] with type
336.     /// [`MemoryRegionType::Mmio`] is returned. Upon failure, an error is returned instead.
337.     ///
338.     pub fn new_mmio(
339.         name: &str,
340.         start: PageAligned<T>,
341.         size: usize,
342.         perm: AccessPermission,
343.         cache_policy: MmioCachePolicy,
344.     ) -> Result<Self, Error> {
345.         let mut region: Self = Self::new(name, start, size, MemoryRegionType::Mmio, perm)?;
346.         region.0.set_cache_policy(cache_policy);
347.         Ok(region)
348.     }
349. 
350.     pub fn from_memory_region(region: MemoryRegion<T>) -> Result<Self, Error> {
351.         let cache_policy: Option<MmioCachePolicy> = region.cache_policy();
352.         let start: T = region.start().align_down(PAGE_ALIGNMENT)?;
353.         let start: PageAligned<T> = PageAligned::from_address(start)?;
354.         let name: String = region.name();
355.         let size: usize = region.size();
356.         let typ: MemoryRegionType = region.typ();
357.         let perm: AccessPermission = region.perm();
358.         let mut truncated: Self = Self::new(&name, start, size, typ, perm)?;
359.         if let Some(policy) = cache_policy {
360.             truncated.0.set_cache_policy(policy);
361.         }
362.         Ok(truncated)
363.     }
364. 
365.     pub fn name(&self) -> String {
366.         self.0.name()
367.     }
368. 
369.     /// Returns the first valid address that lies in the target memory region.
370.     #[verus_spec(result =>
371.         ensures
372.             result@ == self@.start,
373.     )]
374.     pub fn start(&self) -> PageAligned<T> {
375.         self.0.start()
376.     }
377. 
378.     /// Returns the size of the target memory region.
379.     #[verus_spec(result =>
380.         ensures
381.             result as int == self@.size,
382.     )]
383.     pub fn size(&self) -> usize {
384.         self.0.size()
385.     }
386. 
387.     /// Returns the type of the target memory region.
388.     pub fn typ(&self) -> MemoryRegionType {
389.         self.0.typ()
390.     }
391. 
392.     /// Returns the permissions of the target memory region.
393.     pub fn perm(&self) -> AccessPermission {
394.         self.0.perm()
395.     }
396. 
397.     ///
398.     /// # Description
399.     ///
400.     /// Returns the MMIO cache policy of the target memory region, if set.
401.     ///
402.     /// # Returns
403.     ///
404.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
405.     ///
406.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
407.         self.0.cache_policy()
408.     }
409. }
410. 
411. impl<T: Address> PartialEq for TruncatedMemoryRegion<T> {
412.     fn eq(&self, other: &Self) -> bool {
413.         self.0 == other.0
414.     }
415. }
416. 
417. impl<T: Address> Eq for TruncatedMemoryRegion<T> {}
418. 
419. impl<T: Address> PartialOrd for TruncatedMemoryRegion<T> {
420.     fn partial_cmp(&self, other: &Self) -> Option<core::cmp::Ordering> {
421.         Some(self.cmp(other))
422.     }
423. }
424. 
425. impl<T: Address> Ord for TruncatedMemoryRegion<T> {
426.     fn cmp(&self, other: &Self) -> core::cmp::Ordering {
427.         self.0.cmp(&other.0)
428.     }
429. }
430. 
431. impl<T: Address> core::fmt::Debug for TruncatedMemoryRegion<T> {
432.     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
433.         write!(
434.             f,
435.             "TruncatedMemoryRegion {{ name: {}, start: {:?}, size: {}, typ: {:?}, perm: {:?}, \
436.              cache_policy: {:?} }}",
437.             self.name(),
438.             self.start(),
439.             self.size(),
440.             self.typ(),
441.             self.perm(),
442.             self.cache_policy()
443.         )
444.     }
445. }
446. 
447. //==================================================================================================
448. // Standalone Functions
449. //==================================================================================================
450. 
451. impl TruncatedMemoryRegion<PhysicalAddress> {
452.     /// Attempts to create a virtual memory region from a physical memory region.
453.     pub fn from_virtual_memory_region(region: MemoryRegion<VirtualAddress>) -> Result<Self, Error> {
454.         let name: String = region.name();
455.         let start: PageAligned<PhysicalAddress> =
456.             PageAligned::from_address(PhysicalAddress::from_virtual_address(region.start())?)?;
457.         let size: usize = region.size();
458.         let typ: MemoryRegionType = region.typ();
459.         let perm: AccessPermission = region.perm();
460.         TruncatedMemoryRegion::new(&name, start, size, typ, perm)
461.     }
462. }
